        @Override public boolean isOnline(){return true;}@Override public boolean isOp(){return false;}@Override public boolean hasPermission(String permission){return permission.startsWith("neverlandtownydiplomacy.")&&!permission.endsWith(".admin");}@Override public GameMode getGameMode(){return GameMode.SURVIVAL;}@Override public void sendMessage(String text){}@Override public void sendMessage(String...text){}@Override public void sendMessage(net.kyori.adventure.text.Component text){}
